const msg = $json.message;
const text = (msg?.text || "").trim().toLowerCase();

return [{
  json: {
    chatId: msg.chat.id,
    userId: msg.from.id,
    username: msg.from.username || msg.from.first_name,
    rawText: msg.text,
    command: text,
  }
}];

let cmd = ($json.command ?? "").trim().toLowerCase();
const rawText = $json.rawText || cmd;

// Natural-language bridge into the new OpenClaw Proxmox Orchestrator.
if (/(slow|lag|lagging|performance|cpu|ram|memory|diagnose|diagnostic|why)/.test(cmd) && /(ubuntu|test|vm|machine)/.test(cmd)) {
  cmd = 'diagnose vm 105';
}
if (/(idle|unused|cleanup|clean up|save resources|old vms)/.test(cmd)) {
  cmd = 'cleanup vms';
}
if (/(cannot access|can't access|cant access|unreachable|not responding|app down|server down|service down)/.test(cmd)) {
  cmd = 'recover vm 105';
}

const structuredPatterns = [
  /^help$/,
  /^node status$/,
  /^list vms$/,
  /^recent errors$/,
  /^recent tasks$/,
  /^start vm\s+\S+/,
  /^stop vm\s+\S+/,
  /^reboot vm\s+\S+/,
  /^check updates\s+\S+/,
  /^update\s+\S+/,
  /^diagnose vm\s+\S+/,
  /^cleanup vms$/,
  /^recover vm\s+\S+/
];

const isStructured = structuredPatterns.some(p => p.test(cmd));
return [{ json: { command: cmd, rawText, chatId: $json.chatId, userId: $json.userId, username: $json.username, isStructured } }];

const text = ($json.command ?? "").trim().toLowerCase();

// Tokenize
const parts = text.split(/\s+/);

const action = parts[0];        // help, list, start, stop, etc.
const subject = parts[1] || ""; // vm, vms, node
const target = parts[2] || "";  // vmid or name

return [{
  json: {
    ...$json,
    action,
    subject,
    target
  }
}];

const vms = $json.data || [];

const vmList = vms.map(vm =>
  `• ${vm.vmid} — ${vm.name || 'unnamed'} (${vm.status})`
).join('\n');

const helpText = `
🛠 Proxmox Admin Bot — Commands

Available commands:
- help
- list vms
- start vm <vmid>
- stop vm <vmid>
- reboot vm <vmid>
- check updates <vmid>
- update <vmid>

📦 Available VMs:
${vmList || 'No VMs found'}
`;

return [{
  json: {
    chatId: $json.chatId,
    message: helpText
  }
}];

const vms = $json.data || [];

if (!vms.length) {
  return [{
    json: {
      chatId: $json.chatId,
      message: "⚠️ No VMs found on the cluster."
    }
  }];
}

const lines = vms.map(vm => {
  const statusIcon = vm.status === 'running' ? '🟢' : '🔴';
  return `${statusIcon} VMID: ${vm.vmid}\n   Name: ${vm.name || 'unnamed'}\n   Node: ${vm.node}\n   Status: ${vm.status}`;
});

const message = `📦 *Proxmox Virtual Machines*\n\n${lines.join('\n\n')}`;

return [{
  json: {
    chatId: $json.chatId,
    message
  }
}];

// --- 1. Get VMID from the Parse Command node ---
const vmid = String($node["Parse Command"].json.target);

// --- 2. Read HTTP Request response safely ---
const responseItem = $input.all()[0].json;
const vms = Array.isArray(responseItem.data)
  ? responseItem.data
  : [];

// --- 3. Find VM ---
const match = vms.find(vm => String(vm.vmid) === vmid);

// --- 4. VM not found → ERROR ---
if (!match) {
  return [{
    json: {
      chatId: $node["Parse Command"].json.chatId,
      error: true,
      message:
        `❌ VM ID ${vmid} does not exist.\n\n` +
        `Available VM IDs:\n` +
        vms.map(v => `• ${v.vmid} — ${v.name}`).join('\n')
    }
  }];
}

// --- 5. VM exists → enrich context ---
return [{
  json: {
    ...$node["Parse Command"].json,
    vmExists: true,
    vmid: vmid,
    vmName: match.name,
    vmNode: match.node,
    vmStatus: match.status,
    vmType: match.type
  }
}];

